OLD_WAKE = '"""Local wake phrase gate. Ambient transcripts never go to the agent."""\nimport re\nimport time\n\nclass WakeGate:\n    def __init__(self, now=time.monotonic):\n        self.now = now\n        self.until = 0.0\n\n    def accept(self, text):\n        match = re.match(r"^\\s*(?:hey|okay|ok)\\s+care\\s*bridge\\b[\\s,.!?;:]*", text, re.I)\n        if match:\n            command = text[match.end():].strip()\n            self.until = self.now() + 15 if not command else 0.0\n            return command  # empty string means acknowledge and listen for one command\n        if self.now() < self.until:\n            self.until = 0.0\n            return text.strip() or None\n        return None\n\n    def reset(self):\n        self.until = 0.0\n'
WAKE = '"""Local wake phrase gate. Ambient transcripts never go to the agent."""\nimport re\nimport time\n\nclass WakeGate:\n    def __init__(self, now=time.monotonic):\n        self.now = now\n        self.until = 0.0\n\n    def accept(self, text):\n        if "[unk]" in text.lower():\n            self.reset()\n            return None\n        match = re.match(r"^\\s*(?:hey|okay|ok)\\s+care(?:\\s*bridge)?\\b[\\s,.!?;:]*", text, re.I)\n        if match:\n            command = text[match.end():].strip()\n            self.until = self.now() + 15 if not command else 0.0\n            return command  # empty string means acknowledge and listen for one command\n        if self.now() < self.until:\n            self.until = 0.0\n            return text.strip() or None\n        return None\n\n    def reset(self):\n        self.until = 0.0\n'

root = Path.cwd()
planned = []
for name, edits in CHANGES.items():
    path = root / name
    text = path.read_text()
    for before, after in NORMALIZE.get(name, []):
        text = text.replace(after, before)
    for before, after in edits:
        if after in text:
            continue
        if text.count(before) != 1:
            raise SystemExit(f"No files changed: unexpected contents in {name}. Send this error for an updated patch.")
        text = text.replace(before, after)
    if name.endswith('.py'):
        compile(text, name, 'exec')
    planned.append((path, text))
wake_path = root / 'tactidose/agent/wake.py'
if wake_path.exists() and wake_path.read_text() not in (OLD_WAKE, WAKE):
    raise SystemExit('No files changed: wake.py contains other changes.')
for path, text in planned:
    if path.read_text() != text:
        backup = path.with_name(path.name + '.before-hey-care')
        if not backup.exists():
            shutil.copy2(path, backup)
        path.write_text(text)
        print('Updated', path.relative_to(root))
if wake_path.exists() and not wake_path.with_suffix('.py.before-hey-care').exists():
    shutil.copy2(wake_path, wake_path.with_suffix('.py.before-hey-care'))
wake_path.write_text(WAKE)
print('Ready. Restart the app. Say: Hey Care, give me my pill.')
print('Hands-free commands use a limited vocabulary. Use Talk or typing for free-form conversation.')
